draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // bird
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2 - 50, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 - 30);
  ctx.lineTo(W/2 + Math.sin(t)*50, H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 - 40);
  ctx.lineTo(W/2 + Math.sin(t)*50 - 20, H/2 - 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 - 40);
  ctx.lineTo(W/2 + Math.sin(t)*50 + 20, H/2 - 60);
  ctx.stroke();

  // fish
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t)*100, H/2 + 50, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*100, H/2 + 30);
  ctx.lineTo(W/2 + Math.cos(t)*100, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*100, H/2 + 40);
  ctx.lineTo(W/2 + Math.cos(t)*100 - 30, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t)*100, H/2 + 40);
  ctx.lineTo(W/2 + Math.cos(t)*100 + 30, H/2 + 10);
  ctx.stroke();

  ctx.restore();
}
